    const amrex::Real qr =
      k_f *
      (kc_fast ? (ge[6] * inv_ge[10] * inv_ge[5] * ge[9])
               : exp(-(-g_RT[5] + g_RT[6] + g_RT[9] - g_RT[10]))) *
      (sc[5] * sc[10]);
    const amrex::Real qdot = qf - qr;
    wdot[5] += qdot;
    wdot[6] -= qdot;
    wdot[9] -= qdot;
    wdot[10] += qdot;
